     8	/** One question per check. A check is a markdown file, so anyone can add one. */
     9	export interface CheckDefinition {
    10	  name: string;
    11	  description: string;
    12	  prompt: string;
    13	}
    14	
    15	export function parseCheck(source: string): CheckDefinition {
    16	  const match = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(source.replaceAll("\r\n", "\n"));
    17	  if (!match) throw new Error("check is missing frontmatter");
    18	  const fields = Object.fromEntries(
    19	    (match[1] ?? "").split("\n").map((line) => {
    20	      const at = line.indexOf(":");
    21	      return [line.slice(0, at).trim(), line.slice(at + 1).trim()];
    22	    }),
    23	  );
    24	  if (!fields.name) throw new Error("check is missing a name");
    25	  return { name: fields.name, description: fields.description ?? "", prompt: (match[2] ?? "").trim() };
    26	}
    27	
    28	export async function loadChecks(dir: string): Promise<CheckDefinition[]> {
    29	  const entries = (await readdir(dir)).filter((f) => f.endsWith(".md")).sort();
    30	  return Promise.all(entries.map(async (f) => parseCheck(await readFile(join(dir, f), "utf8"))));
    31	}
