     4	/** Plain arithmetic, so a judge can follow every score. No model involved. */
     5	export function riskScore({ blastRadius, originWeight, untested, mastery }: RiskInputs): number {
     6	  return (1 + Math.log1p(blastRadius)) * originWeight * (0.5 + 0.5 * untested) * (1 - mastery);
     7	}
     8	
     9	const overlaps = (a: Claim, b: Claim) =>
    10	  a.location.file === b.location.file &&
    11	  a.location.lines[0] <= b.location.lines[1] &&
    12	  b.location.lines[0] <= a.location.lines[1];
    13	
    14	/** Several checks often spot the same change. Keep the riskiest of each overlap. */
    15	export function dedupeClaims(ranked: RankedClaim[]): RankedClaim[] {
    16	  return ranked.reduce<RankedClaim[]>((kept, claim) => (kept.some((k) => overlaps(k, claim)) ? kept : [...kept, claim]), []);
    17	}
    18	
    19	export function rankClaims(
    20	  claims: Claim[],
    21	  inputsFor: (claim: Claim) => Omit<RiskInputs, "originWeight">,
    22	  config: VivaConfig,
    23	): RankedClaim[] {
    24	  const ranked = claims
    25	    .map((claim) => {
    26	      const inputs = { ...inputsFor(claim), originWeight: config.originWeight[claim.origin] };
    27	      return { ...claim, inputs, risk: riskScore(inputs) };
    28	    })
    29	    .sort((a, b) => b.risk - a.risk);
