     4	const DAY_MS = 86_400_000;
     5	
     6	/** Understanding fades with time, and halves when the code has changed since. */
     7	export function decayedMastery(a: Attestation, currentHash: string | null, now: Date, config: VivaConfig): number {
     8	  const days = Math.max(0, (now.getTime() - new Date(a.at).getTime()) / DAY_MS);
