    62	export async function readReviewFile(repoPath: string, base: string, head: string, file: string): Promise<ReviewFile> {
    63	  const changed = await git(repoPath, ["diff", "--name-only", "-z", `${base}...${head}`]);
    64	  if (!changed.split("\0").includes(file)) return { refused: "not-in-review" };
    65	  const entry = await git(repoPath, ["--literal-pathspecs", "ls-tree", "-l", "-z", head, "--", file]);
    66	  const [mode, type, hash, size] = entry.split("\t")[0]?.trim().split(/\s+/) ?? [];
