 65	    const version = await fogVersion(repoPath).catch(() => null);
 66	    if (version === null || fogVersions.get(repoPath) === version) return;
 67	    fogVersions.set(repoPath, version);
 68	    publish({ type: "fog", repoPath });
 69	  }
